#include <Aevrynd/SceneECS3D.h>
#include <algorithm>
#include <cmath>
#include <new>

namespace Aevrynd {
namespace {
bool Finite(Vec3 value){return std::isfinite(value.x)&&std::isfinite(value.y)&&std::isfinite(value.z);}
bool ValidTransform(const Transform3D& value){return Finite(value.position)&&Finite(value.rotation)&&Finite(value.scale);}
bool ValidMesh(const MeshResource3D& mesh){return bool(mesh)&&Finite(mesh.bounds.center)&&Finite(mesh.bounds.extents)&&std::isfinite(mesh.bounds.radius)&&mesh.bounds.radius>=0.f;}
bool ValidLodLevels(const SceneMeshRenderable3D& component){if(component.lodLevelCount<2||component.lodLevelCount>MaximumMeshLodLevels3D)return false;float previousSwitch{},previousEnd=-std::numeric_limits<float>::infinity();std::size_t previousTriangles=(std::numeric_limits<std::size_t>::max)();for(std::size_t level=0;level<component.lodLevelCount;++level){const MeshLodLevel3D& value=component.lodLevels[level];if(!ValidMesh(value.mesh)||value.mesh.TriangleCount()>previousTriangles)return false;previousTriangles=value.mesh.TriangleCount();if(level+1<component.lodLevelCount){if(!std::isfinite(value.switchDistance)||value.switchDistance<=previousSwitch||!std::isfinite(value.transitionWidth)||value.transitionWidth<0.f)return false;const float halfWidth=value.transitionWidth*.5f,start=value.switchDistance-halfWidth,end=value.switchDistance+halfWidth;if(!std::isfinite(halfWidth)||!std::isfinite(start)||!std::isfinite(end)||start<previousEnd)return false;previousSwitch=value.switchDistance;previousEnd=end;}}return true;}
bool ValidLight(const PointLight3D& light){return Finite(light.position)&&std::isfinite(light.radius)&&light.radius>0.f&&std::isfinite(light.intensity)&&light.intensity>0.f;}
}
SceneEntity3D SceneECSRegistry3D::Create(){std::uint32_t index{};if(freeSlots_.empty()){if(slots_.size()>=(std::numeric_limits<std::uint32_t>::max)())return{};index=static_cast<std::uint32_t>(slots_.size());slots_.emplace_back();slots_.back().generation=1;}else{index=freeSlots_.back();freeSlots_.pop_back();}Slot& slot=slots_[index];slot.alive=true;slot.transform.reset();slot.renderable.reset();slot.pointLight.reset();return{index,slot.generation};}
bool SceneECSRegistry3D::CreateBatchAtomic(std::span<const SceneEntityDefinition3D> definitions,std::vector<SceneEntity3D>& entities){
    std::vector<SceneEntity3D> created;try{created.reserve(definitions.size());}catch(...){return false;}
    try{for(const auto& definition:definitions){const SceneEntity3D entity=Create();if(!entity||(definition.transform&&!SetTransform(entity,*definition.transform))||(definition.renderable&&!SetRenderable(entity,*definition.renderable))||(definition.pointLight&&!SetPointLight(entity,*definition.pointLight))){if(entity)Destroy(entity);for(auto iterator=created.rbegin();iterator!=created.rend();++iterator)Destroy(*iterator);return false;}created.push_back(entity);}}
    catch(...){for(auto iterator=created.rbegin();iterator!=created.rend();++iterator)Destroy(*iterator);return false;}
    try{entities.reserve(entities.size()+created.size());entities.insert(entities.end(),created.begin(),created.end());}catch(...){for(auto iterator=created.rbegin();iterator!=created.rend();++iterator)Destroy(*iterator);return false;}return true;
}
SceneECSRegistry3D::Slot* SceneECSRegistry3D::Find(SceneEntity3D entity){if(entity.index>=slots_.size())return nullptr;Slot& slot=slots_[entity.index];return slot.alive&&slot.generation==entity.generation?&slot:nullptr;}
const SceneECSRegistry3D::Slot* SceneECSRegistry3D::Find(SceneEntity3D entity)const{if(entity.index>=slots_.size())return nullptr;const Slot& slot=slots_[entity.index];return slot.alive&&slot.generation==entity.generation?&slot:nullptr;}
bool SceneECSRegistry3D::Alive(SceneEntity3D entity)const{return Find(entity)!=nullptr;}
bool SceneECSRegistry3D::Destroy(SceneEntity3D entity){Slot* slot=Find(entity);if(!slot)return false;if(slot->generation!=(std::numeric_limits<std::uint32_t>::max)()&&freeSlots_.size()==freeSlots_.capacity()){try{const std::size_t next=(std::max)(std::size_t{8},freeSlots_.capacity()*2);freeSlots_.reserve(next);}catch(const std::bad_alloc&){return false;}}slot->alive=false;slot->transform.reset();slot->renderable.reset();slot->pointLight.reset();if(slot->generation!=(std::numeric_limits<std::uint32_t>::max)()){++slot->generation;freeSlots_.push_back(entity.index);}return true;}
bool SceneECSRegistry3D::DestroyBatchAtomic(std::span<const SceneEntity3D> entities){std::size_t reusable{};for(std::size_t index=0;index<entities.size();++index){if(!Alive(entities[index]))return false;for(std::size_t previous=0;previous<index;++previous)if(entities[previous]==entities[index])return false;if(entities[index].generation!=(std::numeric_limits<std::uint32_t>::max)())++reusable;}if(reusable>freeSlots_.max_size()-freeSlots_.size())return false;try{freeSlots_.reserve(freeSlots_.size()+reusable);}catch(const std::bad_alloc&){return false;}for(const SceneEntity3D entity:entities)if(!Destroy(entity))return false;return true;}
void SceneECSRegistry3D::Clear(){std::vector<std::uint32_t> reusable;reusable.reserve(slots_.size());for(std::uint32_t index=0;index<slots_.size();++index){Slot& slot=slots_[index];if(slot.alive&&slot.generation!=(std::numeric_limits<std::uint32_t>::max)())++slot.generation;slot.alive=false;slot.transform.reset();slot.renderable.reset();slot.pointLight.reset();if(slot.generation!=(std::numeric_limits<std::uint32_t>::max)())reusable.push_back(index);}freeSlots_.swap(reusable);renderableBatch_.clear();pointLightBatch_.clear();lastStats_={};}

bool SceneECSRegistry3D::SetTransform(SceneEntity3D entity,SceneTransformComponent3D component){Slot* slot=Find(entity);if(!slot)return false;slot->transform=std::move(component);return true;}
bool SceneECSRegistry3D::SetRenderable(SceneEntity3D entity,SceneMeshRenderable3D component){Slot* slot=Find(entity);if(!slot)return false;if(component.lodDistanceMetric!=MeshLodDistanceMetric3D::BoundsSurface)component.lodDistanceMetric=MeshLodDistanceMetric3D::Center;if(component.lodLevelCount){if(!ValidLodLevels(component))return false;}else{if(!ValidMesh(component.nearMesh))return false;if(!std::isfinite(component.lodSwitchDistance)||component.lodSwitchDistance<=0.f)component.lodSwitchDistance=40.f;if(!std::isfinite(component.lodTransitionWidth)||component.lodTransitionWidth<0.f)component.lodTransitionWidth=0.f;}slot->renderable=std::move(component);return true;}
bool SceneECSRegistry3D::SetPointLight(SceneEntity3D entity,ScenePointLightComponent3D component){Slot* slot=Find(entity);if(!slot||!ValidLight(component.light))return false;slot->pointLight=std::move(component);return true;}
bool SceneECSRegistry3D::RemoveTransform(SceneEntity3D entity){Slot* slot=Find(entity);if(!slot)return false;return slot->transform.has_value()?slot->transform.reset(),true:false;}
bool SceneECSRegistry3D::RemoveRenderable(SceneEntity3D entity){Slot* slot=Find(entity);if(!slot)return false;return slot->renderable.has_value()?slot->renderable.reset(),true:false;}
bool SceneECSRegistry3D::RemovePointLight(SceneEntity3D entity){Slot* slot=Find(entity);if(!slot)return false;return slot->pointLight.has_value()?slot->pointLight.reset(),true:false;}
SceneTransformComponent3D* SceneECSRegistry3D::Transform(SceneEntity3D entity){Slot* slot=Find(entity);return slot&&slot->transform?&*slot->transform:nullptr;}
SceneMeshRenderable3D* SceneECSRegistry3D::Renderable(SceneEntity3D entity){Slot* slot=Find(entity);return slot&&slot->renderable?&*slot->renderable:nullptr;}
ScenePointLightComponent3D* SceneECSRegistry3D::PointLight(SceneEntity3D entity){Slot* slot=Find(entity);return slot&&slot->pointLight?&*slot->pointLight:nullptr;}
const SceneTransformComponent3D* SceneECSRegistry3D::Transform(SceneEntity3D entity)const{const Slot* slot=Find(entity);return slot&&slot->transform?&*slot->transform:nullptr;}
const SceneMeshRenderable3D* SceneECSRegistry3D::Renderable(SceneEntity3D entity)const{const Slot* slot=Find(entity);return slot&&slot->renderable?&*slot->renderable:nullptr;}
const ScenePointLightComponent3D* SceneECSRegistry3D::PointLight(SceneEntity3D entity)const{const Slot* slot=Find(entity);return slot&&slot->pointLight?&*slot->pointLight:nullptr;}

SceneECSCollectionStats3D SceneECSRegistry3D::Collect(Scene3D& scene,DrawList& draw,std::uint32_t visibilityMask)const{
    renderableBatch_.clear();pointLightBatch_.clear();SceneECSCollectionStats3D stats{};stats.collectionPasses=lastStats_.collectionPasses+1;
    for(std::uint32_t index=0;index<slots_.size();++index){const Slot& slot=slots_[index];if(!slot.alive)continue;++stats.aliveEntities;if(slot.transform)++stats.transformComponents;if(slot.renderable){++stats.renderableComponents;renderableBatch_.push_back(index);}if(slot.pointLight){++stats.pointLightComponents;pointLightBatch_.push_back(index);}}
    for(std::uint32_t index:renderableBatch_){const Slot& slot=slots_[index];const SceneMeshRenderable3D& renderable=*slot.renderable;++stats.renderableCandidates;if(!renderable.visible){++stats.hidden;continue;}if((renderable.layer&visibilityMask)==0){++stats.layerCulled;continue;}if(!slot.transform){++stats.missingTransform;continue;}if(!ValidTransform(slot.transform->value)){++stats.invalidComponents;continue;}if(renderable.lodLevelCount){if(!ValidLodLevels(renderable)){++stats.invalidComponents;continue;}const std::size_t before=scene.MeshCount();scene.MeshLodChain(std::span<const MeshLodLevel3D>{renderable.lodLevels.data(),renderable.lodLevelCount},renderable.lodDistanceMetric,slot.transform->value,renderable.assetLease);if(scene.MeshCount()==before+1)++stats.submittedLodRenderables;else{++stats.invalidComponents;continue;}}else{if(!ValidMesh(renderable.nearMesh)){++stats.invalidComponents;continue;}const bool validLod=ValidMesh(renderable.farMesh)&&renderable.farMesh.TriangleCount()<=renderable.nearMesh.TriangleCount()&&std::isfinite(renderable.lodSwitchDistance)&&renderable.lodSwitchDistance>0.f;if(validLod){const std::size_t before=scene.MeshCount();scene.MeshLod(renderable.nearMesh,renderable.farMesh,{renderable.lodSwitchDistance,renderable.lodTransitionWidth,renderable.lodDistanceMetric},slot.transform->value,renderable.nearMaterial,renderable.farMaterial,renderable.assetLease);if(scene.MeshCount()==before+1)++stats.submittedLodRenderables;else{++stats.invalidComponents;continue;}}else scene.Mesh(renderable.nearMesh,slot.transform->value,renderable.nearMaterial,renderable.assetLease);}++stats.submittedRenderables;}
    for(std::uint32_t index:pointLightBatch_){const Slot& slot=slots_[index];const ScenePointLightComponent3D& component=*slot.pointLight;if(!component.visible){++stats.hidden;continue;}if((component.layer&visibilityMask)==0){++stats.layerCulled;continue;}PointLight3D light=component.light;if(!ValidLight(light)){++stats.invalidComponents;continue;}if(component.inheritTransform){if(!slot.transform){++stats.missingTransform;continue;}if(!ValidTransform(slot.transform->value)){++stats.invalidComponents;continue;}light.position=TransformPoint(slot.transform->value.Matrix(),light.position);if(!Finite(light.position)){++stats.invalidComponents;continue;}}const std::size_t before=draw.PointLights().size();draw.AddPointLight(light);if(draw.PointLights().size()==before+1)++stats.submittedPointLights;else ++stats.invalidComponents;}
    lastStats_=stats;return stats;
}

SceneECSCollectionStats3D SceneECSRegistry3D::Stats()const{return lastStats_;}
ReusableMemoryStats SceneECSRegistry3D::MemoryStats()const{const std::size_t retained=slots_.capacity()*sizeof(Slot)+(freeSlots_.capacity()+renderableBatch_.capacity()+pointLightBatch_.capacity())*sizeof(std::uint32_t);const std::size_t reclaimable=(slots_.capacity()>slots_.size()?(slots_.capacity()-slots_.size())*sizeof(Slot):0)+(freeSlots_.capacity()>freeSlots_.size()?(freeSlots_.capacity()-freeSlots_.size())*sizeof(std::uint32_t):0)+(renderableBatch_.capacity()>renderableBatch_.size()?(renderableBatch_.capacity()-renderableBatch_.size())*sizeof(std::uint32_t):0)+(pointLightBatch_.capacity()>pointLightBatch_.size()?(pointLightBatch_.capacity()-pointLightBatch_.size())*sizeof(std::uint32_t):0);return{retained,reclaimable,lastReleasedBytes_,trimCount_};}
std::size_t SceneECSRegistry3D::TrimUnusedMemory(){const std::size_t before=MemoryStats().retainedCapacityBytes;slots_.shrink_to_fit();freeSlots_.shrink_to_fit();renderableBatch_.clear();renderableBatch_.shrink_to_fit();pointLightBatch_.clear();pointLightBatch_.shrink_to_fit();const std::size_t after=MemoryStats().retainedCapacityBytes;lastReleasedBytes_=before>after?before-after:0;++trimCount_;return lastReleasedBytes_;}
}
